CREATE TABLE "c_Cart" ("id" BIGINT NOT NULL, "a_Cart_status" TEXT NOT NULL, "r_CustomerCart_source_id" BIGINT, "r_CustomerCart_source_dtype" TEXT, PRIMARY KEY ("id"), UNIQUE ("r_CustomerCart_source_id"), CHECK ("r_CustomerCart_source_dtype" IS NULL OR "r_CustomerCart_source_dtype" IN ('Customer')), CHECK ((TRUE) OR "r_CustomerCart_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_CustomerCart_source_id" IS NOT NULL));
CREATE TABLE "c_Order" ("id" BIGINT NOT NULL, "a_Order_total" NUMERIC NOT NULL, "a_Order_ordered_at" TIMESTAMP NOT NULL, "r_CustomerOrders_source_id" BIGINT, "r_CustomerOrders_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_CustomerOrders_source_dtype" IS NULL OR "r_CustomerOrders_source_dtype" IN ('Customer')), CHECK ((TRUE) OR "r_CustomerOrders_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_CustomerOrders_source_id" IS NOT NULL));
CREATE TABLE "c_Product" ("id" BIGINT NOT NULL, "a_Product_sku" TEXT NOT NULL, "a_Product_price" NUMERIC NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Review" ("id" BIGINT NOT NULL, "a_Review_rating" BIGINT NOT NULL, "a_Review_body" TEXT NOT NULL, "r_ProductReviews_source_id" BIGINT, PRIMARY KEY ("id"), CHECK ((TRUE) OR "r_ProductReviews_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_ProductReviews_source_id" IS NOT NULL));
CREATE TABLE "c_User" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Admin_role_level" BIGINT, "a_Customer_loyalty_points" BIGINT, "a_User_email" TEXT, "a_User_created_at" TIMESTAMP, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Admin','Customer','User')), CHECK ((dtype IN ('Admin')) OR "a_Admin_role_level" IS NULL), CHECK (NOT (dtype IN ('Admin')) OR "a_Admin_role_level" IS NOT NULL), CHECK ((dtype IN ('Customer')) OR "a_Customer_loyalty_points" IS NULL), CHECK (NOT (dtype IN ('Customer')) OR "a_Customer_loyalty_points" IS NOT NULL), CHECK ((dtype IN ('Admin','Customer','User')) OR "a_User_email" IS NULL), CHECK (NOT (dtype IN ('Admin','Customer','User')) OR "a_User_email" IS NOT NULL), CHECK ((dtype IN ('Admin','Customer','User')) OR "a_User_created_at" IS NULL), CHECK (NOT (dtype IN ('Admin','Customer','User')) OR "a_User_created_at" IS NOT NULL));
CREATE TABLE "l_OrderProducts" ("r_OrderProducts_source_id" BIGINT NOT NULL, "r_OrderProducts_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_OrderProducts_source_id", "r_OrderProducts_target_id"));
ALTER TABLE "c_Cart" ADD CONSTRAINT "fk_c_Cart_0" FOREIGN KEY ("r_CustomerCart_source_id", "r_CustomerCart_source_dtype") REFERENCES "c_User" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Order" ADD CONSTRAINT "fk_c_Order_0" FOREIGN KEY ("r_CustomerOrders_source_id", "r_CustomerOrders_source_dtype") REFERENCES "c_User" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Review" ADD CONSTRAINT "fk_c_Review_0" FOREIGN KEY ("r_ProductReviews_source_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_OrderProducts" ADD CONSTRAINT "fk_l_OrderProducts_0" FOREIGN KEY ("r_OrderProducts_source_id") REFERENCES "c_Order" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_OrderProducts" ADD CONSTRAINT "fk_l_OrderProducts_1" FOREIGN KEY ("r_OrderProducts_target_id") REFERENCES "c_Product" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;